import { test, expect } from '@playwright/test';

test.describe('File Upload Success Checkmark', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display success checkmark when file upload completes successfully', async ({ page }) => {
    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('playwright/fixtures/sample.pdf');

    // Locate and click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Wait for upload progress to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/upload') && response.status() === 200
    );

    // Verify success checkmark appears using getByRole
    const successCheckmark = page.getByRole('img', { name: /success/i });
    await expect(successCheckmark).toBeVisible();

    // Verify success message is displayed using getByText
    const successMessage = page.getByText(/File uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify file name is displayed in success state
    const fileNameDisplay = page.getByText('sample.pdf');
    await expect(fileNameDisplay).toBeVisible();

    // Verify upload progress bar is no longer visible
    const progressBar = page.locator('[data-testid="upload-progress-bar"]');
    await expect(progressBar).not.toBeVisible();
  });

  test('should not display success checkmark when file upload fails', async ({ page }) => {
    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('playwright/fixtures/large_file.zip');

    // Intercept the upload API call and simulate failure
    await page.route('**/api/upload', route => {
      route.abort('failed');
    });

    // Locate and click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Wait for error response
    await page.waitForResponse(response => 
      response.url().includes('/api/upload') && response.status() === 500
    );

    // Verify success checkmark does not appear
    const successCheckmark = page.getByRole('img', { name: /success/i });
    await expect(successCheckmark).not.toBeVisible();

    // Verify error message is displayed using getByText
    const errorMessage = page.getByText(/Upload failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify file name is still visible in error state
    const fileNameDisplay = page.getByText('large_file.zip');
    await expect(fileNameDisplay).toBeVisible();

    // Verify error icon is displayed using getByRole
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();
  });
});
